#include "WorldAiSpawnBatch.h"
#include "json.hpp"
#include <stdexcept>
#include <unordered_set>
namespace Silver::WorldEditor
{
namespace{using Json=nlohmann::json;constexpr std::size_t MaxBytes=2*1024*1024,MaxCommands=256;
WorldMonsterSpawn S(const Json&j){WorldMonsterSpawn s;s.MapDefinitionId=j.value("mapDefinitionId",std::string{});s.MapVariant=j.value("mapVariant",std::string{});s.Id=j.value("id",NoSpawn);s.PersistentId=j.value("persistentId","");s.MonsterNumber=j.value("monsterNumber",static_cast<std::int16_t>(-1));s.Designation=j.value("designation","");s.ObjectKind=j.value("objectKind","");s.X1=j.value("x1",static_cast<std::uint8_t>(0));s.Y1=j.value("y1",static_cast<std::uint8_t>(0));s.X2=j.value("x2",static_cast<std::uint8_t>(0));s.Y2=j.value("y2",static_cast<std::uint8_t>(0));s.Direction=j.value("direction",static_cast<std::uint8_t>(0));s.Quantity=j.value("quantity",static_cast<std::int16_t>(0));s.SpawnTrigger=j.value("spawnTrigger","");s.WaveNumber=j.value("waveNumber",static_cast<std::uint8_t>(0));s.RespawnDelayMilliseconds=j.value("respawnDelayMilliseconds",static_cast<std::int64_t>(0));return s;}}
WorldAiSpawnBatch WorldAiSpawnBatch::Decode(std::span<const std::uint8_t>b){if(b.empty()||b.size()>MaxBytes)throw std::invalid_argument("AI SpawnBatch fuera de limites.");Json j;try{j=Json::parse(std::string(reinterpret_cast<const char*>(b.data()),b.size()));}catch(const Json::exception&){throw std::invalid_argument("AI SpawnBatch JSON invalido.");}if(j.value("schema","")!=Schema)throw std::invalid_argument("AI SpawnBatch schema incompatible.");WorldAiSpawnBatch x;x.RequestId=j.value("requestId","");x.MapId=j.value("mapId",-1);x.Safety=j.value("safety","");if(x.RequestId.empty()||x.MapId<0||x.Safety!="CANDIDATE_ONLY; NO_AUTO_APPLY"||!j.contains("commands")||!j.at("commands").is_array()||j.at("commands").size()>MaxCommands)throw std::invalid_argument("AI SpawnBatch inseguro/incompleto.");std::unordered_set<SpawnId>ids;for(const auto&v:j.at("commands")){WorldAiSpawnCommand c;c.Id=v.value("id",NoSpawn);c.Expected=S(v.at("expected"));c.Desired=S(v.at("desired"));if(c.Id==NoSpawn||c.Expected.Id!=c.Id||c.Desired.Id!=c.Id||!ids.insert(c.Id).second||c.Expected.PersistentId.empty()||c.Expected.PersistentId!=c.Desired.PersistentId||c.Expected.MonsterNumber!=c.Desired.MonsterNumber||c.Expected.ObjectKind!=c.Desired.ObjectKind)throw std::invalid_argument("AI SpawnBatch intenta cambiar identidad OpenMU/Monster.");x.Commands.push_back(std::move(c));}return x;}
bool WorldAiSpawnBatch::Validate(const WorldMonsterSpawnDocument&d,std::string&e)const{if(!d.Loaded()||d.MapNumber()!=MapId){e="AI SpawnBatch mapa no coincide.";return false;}for(const auto&c:Commands){const auto*p=d.Find(c.Id);if(!p||!(*p==c.Expected)){e="AI Spawn Expected no coincide con Candidate actual.";return false;}const auto*base=d.FindBaseline(c.Id);if(!base||base->PersistentId!=c.Expected.PersistentId){e="AI Spawn persistentId no coincide con baseline OpenMU.";return false;}}e.clear();return true;}
bool WorldAiSpawnBatch::Apply(WorldMonsterSpawnDocument&d,std::string&e)const{if(!Validate(d,e))return false;bool changed=false;for(const auto&c:Commands)changed=d.SetCandidate(c.Id,c.Desired,"AI: Edit Monster Spawn")||changed;if(!changed){e="AI SpawnBatch no produjo cambios.";return false;}e.clear();return true;}
}
